function setLanguage(lang){if(!locales[lang])lang='zh-CN';const t=locales[lang];document.documentElement.lang=lang;document.querySelectorAll('[data-t]').forEach(el=>{el.innerHTML=t[el.dataset.t]});document.querySelector('.brand').setAttribute('aria-label',t.brand);document.querySelector('.hero-art').alt={ 'zh-CN':'金色圆月与月夜中振翅的粉色蝴蝶','zh-TW':'金色圓月與月夜中振翅的粉色蝴蝶',en:'Pink butterflies flying in front of a golden full moon',ja:'金色の満月の前を舞うピンクの蝶',ko:'황금빛 보름달 앞을 나는 분홍색 나비'}[lang];document.querySelectorAll('[data-alt]').forEach(el=>{el.alt=t[el.dataset.alt]});document.title=t.brand+' | '+t.hero1+' '+t.hero2;document.querySelector('meta[name="description"]').content=t.projectIntro;document.querySelector('#language').value=lang;try{localStorage.setItem('zhongqiu-language',lang)}catch{}const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);}
let selected=new URLSearchParams(location.search).get('lang');if(!selected){try{selected=localStorage.getItem('zhongqiu-language')}catch{}}setLanguage(selected||'zh-CN');document.querySelector('#language').addEventListener('change',e=>setLanguage(e.target.value));
